/**
 * WorldForge Tool Catalog Generator
 * ----------------------------------
 * Generates 500+ MCP tools for building 3D world sandbox and story games
 * like GTA6. Each tool is compatible with Claude Code & Claude Desktop.
 *
 * This file is shared between:
 *   - The Next.js web app (catalog browser UI)
 *   - The MCP server mini-service (tool handlers)
 */

export interface ToolInput {
  name: string;
  type: "string" | "number" | "boolean" | "enum" | "array" | "object";
  required: boolean;
  description: string;
  enum?: string[];
  default?: string | number | boolean;
  min?: number;
  max?: number;
}

export interface ToolTemplate {
  suffix: string;
  title: string;
  description: string;
  inputs: ToolInput[];
  returns: string;
  tags: string[];
  sampleText?: string;
}

export interface CategoryDef {
  id: string;
  name: string;
  short: string;
  description: string;
  icon: string;
  color: string;
  accent: string;
  tools: ToolTemplate[];
}

/* ------------------------------------------------------------------ */
/* Helper input builders                                                */
/* ------------------------------------------------------------------ */

const str = (
  name: string,
  description: string,
  required = true,
  def?: string,
): ToolInput => ({ name, type: "string", required, description, default: def });

const num = (
  name: string,
  description: string,
  required = true,
  def?: number,
  min?: number,
  max?: number,
): ToolInput => ({ name, type: "number", required, description, default: def, min, max });

const bool = (
  name: string,
  description: string,
  required = false,
  def?: boolean,
): ToolInput => ({ name, type: "boolean", required, description, default: def });

const en = (
  name: string,
  description: string,
  values: string[],
  required = true,
  def?: string,
): ToolInput => ({ name, type: "enum", required, description, enum: values, default: def });

const arr = (name: string, description: string, required = true): ToolInput => ({
  name,
  type: "array",
  required,
  description,
});

const obj = (name: string, description: string, required = true): ToolInput => ({
  name,
  type: "object",
  required,
  description,
});

